import type { SchoolSubjectResponse } from "./school-subject.response";

/**
 * Type: Response
 * Description: Represents the grade of a student in a specific evaluation of a school subject within an academic cycle enrollment
 */
export interface StudentGradeResponse {
    /**
     * Unique identifier for the student grade, generated by backend
     */
    id: string;
    /**
     * Grade value for the student in a specific evaluation of a school subject
     */
    grade: number;
    /**
     * Number of the evaluation for which the grade is recorded, indicating the sequence of evaluations within the academic cycle
     */
    evaluationNumber: number;
    /**
     * Identifier of the associated school subject for which the grade is recorded
     */
    schoolSubjectId: string;
    /**
     * Reference to the associated school subject that comes from academic cycle school subject
     */
    schoolSubject?: SchoolSubjectResponse;
    /**
     * Identifier of the associated academic cycle enrollment for which the grade is recorded, linking the grade to a specific student's enrollment in an academic cycle group
     */
    academicCycleEnrollmentId: string;
}
